-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["df0451d5ef1fba27"] = { "Si rivolse per primo allo Stormo di Ysera. ⟦Merithra of the Dream=Merithra del Sogno⟧ rispose alla sua chiamata e, da lì, furono avvisati anche lo Stormo di Alexstrasza e lo Stormo di Malygos.", "." },
  ["df052df6a0c83e8b"] = { "Branco di incapaci!\n\nI miei piani prevedevano che entrambi i ponti fossero distrutti nello stesso momento. E voi, teppisti senza cervello, cosa fate? Fate solo metà del lavoro e mettete in allarme l'intera ⟦Alliance=Alleanza⟧ sulle nostre intenzioni. Idioti, ecco cosa siete!\n\nAvete un'unica possibilità di rimediare. Abbiamo una scorta di esplosivi di riserva negli ⟦Arathi Highlands=Altopiani d'Arathi⟧, non lontano dal ponte.\n\nFinite il lavoro, se ci tenete alle vostre misere vite!\n\n--⟦Kam Deepfury=Kam Furiafonda⟧", "." },
  ["df18beae5cf63293"] = { "Possenti guerrieri difendono la nostra casa. I nostri sciamani guidano i nostri spiriti e ci mostrano il passato dei nostri antenati. E i nostri druidi ci aiutano a scoprire la volontà della Madre Terra.\n\nMa tu appartieni ai nostri cacciatori, e i nostri cacciatori apprendono molti aspetti di quei ruoli e li fondono insieme. Scoprirai di rappresentare il cuore del nostro popolo: alcuni della nostra tribù si rivolgeranno a te per una guida, altri per protezione. È mio dovere assicurarmi che tu abbia la preparazione necessaria. Cercami a ⟦Camp Narache=Campo Narache⟧.\n\n-Lanka Farshot, istruttrice dei cacciatori", "." },
  ["df358db9fb07080c"] = { "Con uno sforzo congiunto, Medivh e gli stregoni del ⟦Shadow Council=Concilio dell'Ombra⟧ aprirono il varco dimensionale noto come Portale Oscuro. Questo portale colmava la distanza tra Azeroth e Draenor, ed era abbastanza grande da permettere il passaggio di interi eserciti. Gul'dan mandò esploratori orchi attraverso il portale a perlustrare le terre che avrebbero conquistato. Al loro ritorno, gli esploratori assicurarono al ⟦Shadow Council=Concilio dell'Ombra⟧ che il mondo di Azeroth era pronto per essere preso.", "." },
  ["df65ea233f804040"] = { "I grandi draghi furono allarmati dalla cupa notizia e ipotizzarono che, finché il Pozzo fosse esistito, la Legione avrebbe potuto un giorno tornare e assalire di nuovo il mondo. Malfurion e i tre draghi strinsero un patto per proteggere il Pozzo e assicurarsi che gli agenti della Legione Infuocata non trovassero mai la via del ritorno nel mondo.", "." },
  ["df7d1e06624defa4"] = { "Corremmo a perdifiato fino al campo base, senza mai rallentare. Più tardi quella notte sedemmo in silenzio attorno al fuoco, sapendo che le nostre vite erano state salvate da uno strano scherzo del destino. Tali sono i rischi del cacciatore di grossa selvaggina. Giochiamo con il destino dispensandolo. Eppure ognuno di noi, prima o poi, dovrà affrontare le zanne affilate del destino. Questo Nano è solo felice che quel momento non sia giunto sulle verdi colline di Rovotorto.", "." },
  ["dfd4eebda3259d5d"] = { "Mentre Hellscream e i suoi fedeli guerrieri ⟦Warsong=Cantaguerra⟧ si aggiravano nelle foreste di ⟦Ashenvale=Valtetra⟧, si scontrarono con le antiche ⟦Sentinels=Sentinelle⟧ degli elfi della notte. Convinto che gli orchi fossero tornati alle loro abitudini bellicose, il semidio Cenarius si fece avanti per ricacciare indietro Hellscream e i suoi orchi. Eppure Hellscream e i suoi orchi, sopraffatti da un odio e da una furia soprannaturali, riuscirono a uccidere Cenarius e a corrompere le antiche foreste.", "." },
  ["dfdd9adf3b76da2b"] = { "Il canto di ⟦Ameth'Aran=Ameth'aran⟧\n\nA lungo i figli delle stelle avevano dimorato sulle rive delle acque scintillanti del pozzo eterno. A tutti era noto che Elune, Luce dell'Eterno Crepuscolo, Aspetto e Dea della Luna, dimorava nelle sue acque quando riposava dalle sue opere. Sulle sponde del pozzo i figli delle stelle, prediletti di Elune, costruirono le loro case. E intanto il loro sguardo era sempre rivolto al cielo, verso la notte illuminata dalla luna.", "." },
})
